/**
 * The opening chime — Bookliz's "ta-dum".
 *
 * Two warm notes rise as the sun comes up, with a small glint on top. It
 * starts with the sun in the animated splash (see AnimatedSplash) and lasts
 * about a second and a half. It is the only sound of its kind in the app.
 *
 * It respects the silent switch, mixes with whatever music is playing
 * instead of stopping it, and can be turned off in Settings ("Opening
 * sound"). The sound itself is generated by scripts/splash-sound.py (python3, numpy, scipy).
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { createAudioPlayer } from "expo-audio";
import { claimAmbientSession } from "./audioSession";

const KEY = "booklio:v2:openingSound";
const VOLUME = 0.8;
const RELEASE_AFTER_MS = 4500;

export async function loadOpeningSoundEnabled(): Promise<boolean> {
  try {
    return (await AsyncStorage.getItem(KEY)) !== "off";
  } catch {
    return true;
  }
}

export async function setOpeningSoundEnabled(on: boolean): Promise<void> {
  try {
    await AsyncStorage.setItem(KEY, on ? "on" : "off");
  } catch {
    // Not worth an error: next launch just uses the default.
  }
}

/** Plays the chime once, if it is switched on. Never throws. */
export async function playOpeningSound(): Promise<void> {
  try {
    if (!(await loadOpeningSoundEnabled())) return;
    await claimAmbientSession();
    const player = createAudioPlayer(require("../../assets/sounds/opening.m4a"));
    player.volume = VOLUME;
    player.play();
    setTimeout(() => {
      try {
        player.remove();
      } catch {
        // already gone
      }
    }, RELEASE_AFTER_MS);
  } catch {
    // A missing chime must never get in the way of opening the app.
  }
}
